338	    fn backup_to_path() -> Result<()> {
339	        let src = Connection::open_in_memory()?;
340	        src.execute_batch("CREATE TABLE foo AS SELECT 42 AS x")?;
341	
342	        let temp_dir = tempfile::tempdir().unwrap();
343	        let path = temp_dir.path().join("test.db3");
344	
345	        fn progress(_: Progress) {}
346	
347	        src.backup(MAIN_DB, path.as_path(), Some(progress))?;
348	        src.backup(MAIN_DB, path.as_path(), NO_PROGRESS)?;
349	
350	        let mut dst = Connection::open_in_memory()?;
351	        dst.restore(MAIN_DB, path.as_path(), Some(progress))?;
352	        dst.restore(MAIN_DB, path, NO_PROGRESS)?;
353	
354	        Ok(())
355	    }
356	
357	    #[test]
358	    fn test_backup() -> Result<()> {
359	        let src = Connection::open_in_memory()?;
360	        let sql = "BEGIN;
361	                   CREATE TABLE foo(x INTEGER);
