300	    /// direct implementation of "Example 2: Online Backup of a Running
301	    /// Database" from [SQLite's Online Backup API documentation](https://www.sqlite.org/backup.html).
302	    ///
303	    /// If `progress` is not `None`, it will be called after each step with the
304	    /// current progress of the backup. Note that is possible the progress may
305	    /// not change if the step returns `Busy` or `Locked` even though the
306	    /// backup is still running.
307	    ///
308	    /// # Failure
309	    ///
310	    /// Will return `Err` if any of the calls to [`step`](Backup::step) return
311	    /// `Err`.
312	    pub fn run_to_completion(
313	        &self,
314	        pages_per_step: c_int,
315	        pause_between_pages: Duration,
316	        progress: Option<fn(Progress)>,
317	    ) -> Result<()> {
318	        use self::StepResult::{Busy, Done, Locked, More};
319	
320	        assert!(pages_per_step > 0, "pages_per_step must be positive");
321	
322	        loop {
323	            let r = self.step(pages_per_step)?;
324	            if let Some(progress) = progress {
325	                progress(self.progress());
326	            }
327	            match r {
328	                More | Busy | Locked => thread::sleep(pause_between_pages),
329	                Done => return Ok(()),
330	            }
331	        }
332	    }
333	
334	    /// Like [`run_to_completion`](Backup::run_to_completion), but instead of
335	    /// waiting forever when the source is busy or locked, this method lets the
336	    /// caller observe every attempt and abort the run.
337	    ///
338	    /// The backup is driven by repeated calls to
339	    /// [`step(pages_per_step)`](Backup::step), sleeping for
340	    /// `pause_between_pages` between attempts (a duration of zero is allowed).
341	    /// After each attempt, `progress` is called exactly once with the
342	    /// attempt's [`StepResult`] and the [`Progress`] at that moment; unlike the
343	    /// callback of [`run_to_completion`](Backup::run_to_completion), it may be
344	    /// a closure that borrows and mutates its environment. It returns `true`
345	    /// to keep going or `false` to stop:
346	    ///
347	    /// - [`Done`](StepResult::Done) means the backup has finished; the return
348	    ///   value of the closure is ignored and [`BackupStatus::Completed`] is
349	    ///   returned even if it returned `false`.
350	    /// - [`More`](StepResult::More) resets the consecutive lock-conflict
351	    ///   counter; returning `false` ends the run with
352	    ///   [`BackupStatus::Aborted`].
353	    /// - [`Busy`](StepResult::Busy) and [`Locked`](StepResult::Locked) share a
354	    ///   single consecutive-conflict counter, which starts at zero for every
355	    ///   call to this method: the first conflict counts as one, and
356	    ///   [`More`](StepResult::More) clears it. When the counter reaches
357	    ///   `max_lock_conflicts` after notifying the closure, returning `false`
358	    ///   yields [`BackupStatus::Aborted`]; returning `true` yields the
359	    ///   `SQLITE_BUSY` / `SQLITE_LOCKED` error of that last attempt without
360	    ///   trying again.
361	    /// - Any other SQLite error from an attempt is returned immediately,
362	    ///   as-is, without notifying the closure or retrying.
363	    ///
364	    /// Neither an abort nor exhausting the lock-conflict budget consumes the
365	    /// backup: the [`Backup`] handle stays usable for further manual
366	    /// [`step`](Backup::step) calls or another run of this method. Only this
367	    /// method's retry loop ends, and the connection's busy-handler settings are
368	    /// untouched.
369	    ///
370	    /// If the source database is modified by another connection while the
371	    /// backup is in progress, SQLite may restart it and the reported page
372	    /// counts may go backwards; they are always passed through verbatim.
373	    ///
374	    /// # Failure
375	    ///
376	    /// Returns [`Error::InvalidBackupParameter`] if `pages_per_step` or
377	    /// `max_lock_conflicts` is not positive. In that case no page is copied and
378	    /// `progress` is not called. Also returns `Err` for any non-transient
379	    /// SQLite error, or for the lock-conflict limit described above.
380	    ///
381	    /// ```rust,no_run
382	    /// # use rusqlite::{backup, Connection};
383	    /// # use std::time::Duration;
384	    /// # fn run(src: &Connection, dst: &mut Connection) -> rusqlite::Result<()> {
385	    /// use backup::{BackupStatus, StepResult};
386	    ///
387	    /// let backup = backup::Backup::new(src, dst)?;
388	    /// let mut conflicts = 0;
389	    /// let mut aborted = false;
390	    /// match backup.run_to_completion_with_progress(
391	    ///     100,
392	    ///     Duration::from_millis(100),
393	    ///     10,
394	    ///     |result, _progress| {
395	    ///         match result {
396	    ///             StepResult::Busy | StepResult::Locked => conflicts += 1,
397	    ///             _ => {}
398	    ///         }
399	    ///         // Give up after at most five attempts.
400	    ///         conflicts < 5
401	    ///     },
402	    /// )? {
403	    ///     BackupStatus::Completed => {}
404	    ///     BackupStatus::Aborted => aborted = true,
405	    ///     // `BackupStatus` is `#[non_exhaustive]`.
